} ',FALSE,TRUE,NULL,510, t.itenantid FROM ui.tenants t WHERE itenantid =24 ;
INSERT INTO ui.dashboardquery(idashboardqueryid, bparametersrequired, vcfilterparametersjson, vcdashboardquery, formattingrequiered, runonanalytics, transposerequired, imenustructuredesc, itenantid) SELECT 89,TRUE,'{  "DateRange": null }','SELECT makeruser.vcusername as "User Name", r.dtactivity  as  "Time stamp", r.vcactivity as "UI", r.vcparameters as "Query Parameter" FROM ui.activitylog r left join ui.webuser makeruser on makeruser.iuserid = r.iuserid where makeruser.iuserid in (select webuserid from ui.webusermapping where mappingid = :tenantid and mappingtype = ''Tenant'') and cast(r.dtactivity at time zone :timeZone as date) between cast(:StartDate as date) and cast(:EndDate as date);',FALSE,FALSE,FALSE,577, t.itenantid FROM ui.tenants t WHERE itenantid =24 ;
INSERT INTO ui.dashboardquery(idashboardqueryid, bparametersrequired, vcfilterparametersjson, vcdashboardquery, formattingrequiered, runonanalytics, transposerequired, imenustructuredesc, itenantid) SELECT 83,TRUE,'{  "DateRange": null }','SELECT r.vcclassname as "Class Name", r.iclassid as "Class ID",  d.vcdecisionname as "Decision Name", p.vcproductname as "Product Name", c.vcchannelname as "Channel Name", makeruser.vcusername as "Maker User", r.dtentrystamp  as "Maker Time Stamp", r.vcremark as "Maker & Checker Remarks", checkeruser.vcusername as "Checker User", r.dtapproverstamp  as "Checker Time Stamp", case when r.vcaction = ''A'' then ''Add'' when r.vcaction = ''M'' then ''Modify'' when r.vcaction = ''X'' then ''Delete'' when r.vcaction = ''N'' then ''No Change'' end as "Action", r.bpayeemandatory as "Payee Mandatory", r.bpayermandatory  as "Payer Mandatory", cast(r.vcdecisionparams as text)   as "Decision Parameters", r.skipprocessing   as "Skip Processing", cast(r.attribs as text) as "Attribs" FROM ui.transactionclassesaudit r left join ui.decisions d on r.idecisionid = d.idecisionid left join masters.products p on r.iproductid = p.iproductid left join masters.channels c on r.ichannelid = c.ichannelid left join ui.webuser makeruser on makeruser.iuserid = r.ientryuserid left join ui.webuser checkeruser on checkeruser.iuserid = r.iapproveruserid where r.itenantid = :tenantid and cast(r.dtentrystamp as date) between cast(:StartDate as date) and cast(:EndDate as date);',FALSE,FALSE,FALSE,577, t.itenantid FROM ui.tenants t WHERE itenantid =24 ;
INSERT INTO ui.dashboardquery(idashboardqueryid, bparametersrequired, vcfilterparametersjson, vcdashboardquery, formattingrequiered, runonanalytics, transposerequired, imenustructuredesc, itenantid) SELECT 10,TRUE,'{"Date" : null, "LocationAddress" : null}','select adm3 as "District",b.* from profiles.sp_getdatalocation_c(:Date, :LocationAddress)b, masters.cities where cities.icityid= b."location.ilocationid"',NULL,NULL,NULL,NULL, t.itenantid FROM ui.tenants t WHERE itenantid =24 ;
INSERT INTO ui.dashboardquery(idashboardqueryid, bparametersrequired, vcfilterparametersjson, vcdashboardquery, formattingrequiered, runonanalytics, transposerequired, imenustructuredesc, itenantid) SELECT 84,TRUE,'{  "DateRange": null }','SELECT r.vcdecisionname as "Decision Name", r.vcdecisiondetail  as "Decision Description",  r.idecisionid as "Decision ID", makeruser.vcusername as "Maker User", r.dtentrystamp  as "Maker Time Stamp", r.vcremark as "Maker & Checker Remarks", checkeruser.vcusername as "Checker User", r.dtapproverstamp  as "Checker Time Stamp", case when r.vcaction = ''A'' then ''Add'' when r.vcaction = ''M'' then ''Modify'' when r.vcaction = ''X'' then ''Delete'' when r.vcaction = ''N'' then ''No Change'' end as "Action", cast(r.vcresultparams as text) as "Decision Parameters", p.vcproductname as "Product Name", cast(r.attribs as text) as "Attributes", r.vcdecisionmapinfo as "Decision Info" FROM ui.decisionsworkflowaudit r left join masters.products p on r.iproductid = p.iproductid left join ui.webuser makeruser on makeruser.iuserid = r.ientryuserid left join ui.webuser checkeruser on checkeruser.iuserid = r.iapproveruserid where r.itenantid = :tenantid and cast(r.dtentrystamp at time zone :timeZone as date) between cast(:StartDate as date) and cast(:EndDate as date);',FALSE,FALSE,FALSE,577, t.itenantid FROM ui.tenants t WHERE itenantid =24 ;
INSERT INTO ui.dashboardquery(idashboardqueryid, bparametersrequired, vcfilterparametersjson, vcdashboardquery, formattingrequiered, runonanalytics, transposerequired, imenustructuredesc, itenantid) SELECT 59,FALSE,NULL,'SELECT string_agg (DISTINCT grp.name_, '', '') as "Group Name",
task.assignee_ as "Analyst Name",
count(distinct CASE
WHEN DATE_PART(''day'', current_timestamp -  CASE
WHEN  oplog.timestamp_ is not null THEN oplog.timestamp_
WHEN  oplog.timestamp_ is null THEN task.create_time_
ELSE null END ) > 30 THEN task.proc_inst_id_
ELSE null
END) as "Above 30 days",
count(distinct CASE
WHEN DATE_PART(''day'', current_timestamp -  CASE
WHEN  oplog.timestamp_ is not null THEN oplog.timestamp_
WHEN  oplog.timestamp_ is null THEN task.create_time_
ELSE null END ) between 20 and 30 THEN task.proc_inst_id_
ELSE null
END) as "30 days to 20 days",
count(distinct CASE
WHEN DATE_PART(''day'', current_timestamp -  CASE
WHEN  oplog.timestamp_ is not null THEN oplog.timestamp_
WHEN  oplog.timestamp_ is null THEN task.create_time_
ELSE null END ) between 10 and 20 THEN task.proc_inst_id_
ELSE null
END) as "20 days to 10 days",
count(distinct CASE
WHEN DATE_PART(''day'', current_timestamp -  CASE
WHEN  oplog.timestamp_ is not null THEN oplog.timestamp_
WHEN  oplog.timestamp_ is null THEN task.create_time_
ELSE null END ) < 10 THEN task.proc_inst_id_
ELSE null
END) as "below 10 days"
FROM
camunda.act_ru_task task
right join camunda.act_re_procdef pdef on task.proc_def_id_ = pdef.id_
full outer join camunda.act_hi_identitylink oplog on oplog.id_ = (select id_ from camunda.act_hi_identitylink where task_id_ = task.id_ and type_ = ''assignee'' and user_id_ = task.assignee_ order by timestamp_ desc limit 1)
right join camunda.act_id_membership memb on task.assignee_ = memb.user_id_
right join camunda.act_hi_identitylink idl on idl.task_id_ = task.id_ and idl.type_= ''candidate''
left join camunda.act_id_group grp on grp.id_ = idl.group_id_ and grp.id_ = memb.group_id_
where task.assignee_ is not null and task.tenant_id_ = :tenantidstr
group by task.assignee_
order by string_agg(DISTINCT grp.name_, '', '') asc',FALSE,FALSE,FALSE,536, t.itenantid FROM ui.tenants t WHERE itenantid =24 ;

UPDATE ui.dashboardquery SET
vcdashboardquery = 'SELECT string_agg (DISTINCT grp.name_, '', '') as "Group Name",
cuser.email_ as "Analyst Name",
count(distinct CASE
WHEN DATE_PART(''day'', current_timestamp -  CASE
WHEN  oplog.timestamp_ is not null THEN oplog.timestamp_
WHEN  oplog.timestamp_ is null THEN task.create_time_
ELSE null END ) > 30 THEN task.proc_inst_id_
ELSE null
END) as "Above 30 days",
count(distinct CASE
WHEN DATE_PART(''day'', current_timestamp -  CASE
WHEN  oplog.timestamp_ is not null THEN oplog.timestamp_
WHEN  oplog.timestamp_ is null THEN task.create_time_
ELSE null END ) between 20 and 30 THEN task.proc_inst_id_
ELSE null
END) as "30 days to 20 days",
count(distinct CASE
WHEN DATE_PART(''day'', current_timestamp -  CASE
WHEN  oplog.timestamp_ is not null THEN oplog.timestamp_
WHEN  oplog.timestamp_ is null THEN task.create_time_
ELSE null END ) between 10 and 20 THEN task.proc_inst_id_
ELSE null
END) as "20 days to 10 days",
count(distinct CASE
WHEN DATE_PART(''day'', current_timestamp -  CASE
WHEN  oplog.timestamp_ is not null THEN oplog.timestamp_
WHEN  oplog.timestamp_ is null THEN task.create_time_
ELSE null END ) < 10 THEN task.proc_inst_id_
ELSE null
END) as "below 10 days"
FROM
camunda.act_ru_task task
right join camunda.act_re_procdef pdef on task.proc_def_id_ = pdef.id_
full outer join camunda.act_hi_identitylink oplog on oplog.id_ = (select id_ from camunda.act_hi_identitylink where task_id_ = task.id_ and type_ = ''assignee'' and user_id_ = task.assignee_ order by timestamp_ desc limit 1)
right join camunda.act_id_user cuser on task.assignee_ = cuser.id_
right join camunda.act_id_membership memb on task.assignee_ = memb.user_id_
right join camunda.act_hi_identitylink idl on idl.task_id_ = task.id_ and idl.type_= ''candidate''
left join camunda.act_id_group grp on grp.id_ = idl.group_id_ and grp.id_ = memb.group_id_
where task.assignee_ is not null and task.tenant_id_ = :tenantidstr
group by cuser.id_
order by string_agg(DISTINCT grp.name_, '', '') asc'::text WHERE
idashboardqueryid = 59 and itenantid =24 ;

