INSERT INTO ui.dashboardquery(idashboardqueryid, bparametersrequired, vcfilterparametersjson, vcdashboardquery, formattingrequiered, runonanalytics, transposerequired, imenustructuredesc, itenantid) SELECT 80,TRUE,'{"DateRange":null}','SELECT "Date",
"Class",
SUM ("Txns Failed to Process") AS "Txns Failed to Process",
SUM("Txns Processed Successfully") AS "Txns Processed Successfully" ,
SUM("Txns Failed to Process") + SUM("Txns Processed Successfully") AS "Txn Requests Received"
FROM
(select
date(sr.dtentrydatetime) as "Date",
cast(vcrequestdata as json)->''txn''->>''class'' as "Class",
case when sr.vcrequestid is null then 0 else 1 end  as "Txns Failed to Process",
case when sr.vcrequestid is null then 1 else 0 end  as "Txns Processed Successfully"
from
analytics.scorerequests sr
WHERE sr.dtentrydatetime between :StartDate and :EndDate and sr.itenantid = :tenantid

UNION ALL
select
date(tx.dttrxntime) as "Date",
tx.vcclassname as "Class",
case when tx.vcmsgid is null then 1 else 0 end  as "Txns Failed to Process",
case when tx.vcmsgid is null then 0 else 1 end  as "Txns Processed Successfully"
from
analytics.trans tx
WHERE tx.dttrxntime between :StartDate and :EndDate and tx.itenantid = :tenantid
 ) T GROUP BY "Date",
"Class";',FALSE,TRUE,FALSE,577, t.itenantid FROM ui.tenants t WHERE itenantid =24 ;
INSERT INTO ui.dashboardquery(idashboardqueryid, bparametersrequired, vcfilterparametersjson, vcdashboardquery, formattingrequiered, runonanalytics, transposerequired, imenustructuredesc, itenantid) SELECT 62,TRUE,'{"DateRange" : null, "CaseType" : null, "Status" : null } ','{
    "All": {
        "Claimed": "select task.name_ as \"Stage\", task.assignee_ as \"Claimed By\", hiproinst.start_time_ \"Created Date\", CASE WHEN  task.assignee_ is not null THEN ''Claimed'' ELSE ''Unclaimed'' END as \"Status\", pdef.name_ as \"Case Type\", CASE WHEN task.assignee_ is not null THEN oplog.time_ ELSE null END  as \"Claimed On\", payer.text_ as \"Payer\", payee.text_ as \"Payee\", TransactionAmount.double_ / 100 as \"Amount\", TicketID.long_ as \"Case ID\", Alert.text_ as \"Alert\" , null as  \"Closed Date\" , null as  \"Closed By\" , CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) =''array'' then cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''observations''->''vpa''->>''vcexternaladdressid'' else  cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''observations''->''vpa''->>''vcexternaladdressid'' END  as \"VPA\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) =''array'' then cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''observations''->''account''->>''vcexternalaccountid'' else  cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''observations''->''account''->>''vcexternalaccountid'' END  as \"Account\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) =''array'' then cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''observations''->''customer''->>''vcexternalcustid'' else  cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''observations''->''customer''->>''vcexternalcustid'' END  as \"Customer\" from camunda.act_ru_task task right join camunda.act_re_procdef pdef on pdef.id_ = task.proc_def_id_ full outer join camunda.act_hi_detail oplog on oplog.id_ = (select id_ from camunda.act_hi_detail where proc_inst_id_ = task.proc_inst_id_ and name_ = ''userActivity'' order by time_ desc limit 1) full outer join camunda.act_ru_variable payer on payer.proc_inst_id_ = task.proc_inst_id_ and payer.name_ = ''payer'' full outer join camunda.act_ru_variable payee on payee.proc_inst_id_ = task.proc_inst_id_ and payee.name_ = ''payee'' full outer join camunda.act_ru_variable  TransactionAmount on TransactionAmount.proc_inst_id_ = task.proc_inst_id_ and TransactionAmount.name_ = ''TransactionAmount'' right join camunda.act_ru_variable  TicketID on TicketID.proc_inst_id_ = task.proc_inst_id_ and TicketID.name_ = ''TicketID'' full outer join camunda.act_ru_variable Alert on Alert.proc_inst_id_ = task.proc_inst_id_ and Alert.name_ = ''Alert'' full outer join camunda.act_hi_varinst  Txn on Txn.proc_inst_id_ = task.proc_inst_id_ and Txn.name_ = ''Transaction'' full outer join camunda.act_ge_bytearray Txnorg on Txnorg.id_ = Txn.bytearray_id_ inner join  camunda.act_hi_procinst hiproinst  on hiproinst.proc_inst_id_ = task.proc_inst_id_ where cast(hiproinst.start_time_ as date)  between cast(:StartDate as date) and cast(:EndDate as date)   and task.assignee_ is not null and hiproinst.proc_def_key_ in (with d1 as (select mappingid from ui.webusermapping where webuserid = :loggedinuser and mappingtype = ''Workflow'') (select workflowkey FROM ui.workflowmasters where (workflowid in (select mappingid from d1) or -1 in (select mappingid from d1)) and itenantid=:tenantid and is_filter_display=true)) and hiproinst.tenant_id_= :tenantidstr",
        "Unclaimed": "select task.name_ as \"Stage\", task.assignee_ as \"Claimed By\", hiproinst.start_time_ \"Created Date\", CASE WHEN  task.assignee_ is not null THEN ''Claimed'' ELSE ''Unclaimed'' END as \"Status\", pdef.name_ as \"Case Type\", CASE WHEN  task.assignee_ is not null THEN oplog.time_ ELSE null END  as \"Claimed On\", payer.text_ as \"Payer\", payee.text_ as \"Payee\", TransactionAmount.double_ / 100 as \"Amount\", TicketID.long_ as \"Case ID\", Alert.text_ as \"Alert\" , null as  \"Closed Date\" ,null as  \"Closed By\" , CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) =''array'' then cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''observations''->''vpa''->>''vcexternaladdressid'' else  cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''observations''->''vpa''->>''vcexternaladdressid'' END  as \"VPA\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) =''array'' then cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''observations''->''account''->>''vcexternalaccountid'' else  cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''observations''->''account''->>''vcexternalaccountid'' END  as \"Account\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) =''array'' then cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''observations''->''customer''->>''vcexternalcustid'' else  cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''observations''->''customer''->>''vcexternalcustid'' END  as \"Customer\" from camunda.act_ru_task task right join camunda.act_re_procdef pdef on pdef.id_ = task.proc_def_id_ full outer join camunda.act_hi_detail oplog on oplog.id_ = (select id_ from camunda.act_hi_detail where proc_inst_id_ = task.proc_inst_id_ and name_ = ''userActivity'' order by time_ desc limit 1) full outer join camunda.act_ru_variable payer on payer.proc_inst_id_ = task.proc_inst_id_ and payer.name_ = ''payer'' full outer join camunda.act_ru_variable payee on payee.proc_inst_id_ = task.proc_inst_id_ and payee.name_ = ''payee'' full outer join camunda.act_ru_variable  TransactionAmount on TransactionAmount.proc_inst_id_ = task.proc_inst_id_ and TransactionAmount.name_ = ''TransactionAmount'' right join camunda.act_ru_variable  TicketID on TicketID.proc_inst_id_ = task.proc_inst_id_ and TicketID.name_ = ''TicketID'' full outer join camunda.act_ru_variable Alert on Alert.proc_inst_id_ = task.proc_inst_id_ and Alert.name_ = ''Alert'' full outer join camunda.act_hi_varinst  Txn on Txn.proc_inst_id_ = task.proc_inst_id_ and Txn.name_ = ''Transaction'' full outer join camunda.act_ge_bytearray Txnorg on Txnorg.id_ = Txn.bytearray_id_ inner join  camunda.act_hi_procinst hiproinst  on hiproinst.proc_inst_id_ = task.proc_inst_id_ where cast(hiproinst.start_time_ as date)  between cast(:StartDate as date) and cast(:EndDate as date)  and task.assignee_ is null and hiproinst.proc_def_key_ in (with d1 as (select mappingid from ui.webusermapping where webuserid = :loggedinuser and mappingtype = ''Workflow'') (select workflowkey FROM ui.workflowmasters where (workflowid in (select mappingid from d1) or -1 in (select mappingid from d1)) and itenantid=:tenantid and is_filter_display=true)) and hiproinst.tenant_id_= :tenantidstr",
        "All": "select CASE WHEN  hiproinst.state_ != ''ACTIVE'' THEN CASE WHEN  closedby.assignee_ is not null THEN closedby.assignee_ ELSE ''Auto Closed'' END ELSE null END as \"Closed By\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) =''array'' then cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''observations''->''vpa''->>''vcexternaladdressid'' else  cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''observations''->''vpa''->>''vcexternaladdressid'' END  as \"VPA\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) =''array'' then cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''observations''->''account''->>''vcexternalaccountid'' else  cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''observations''->''account''->>''vcexternalaccountid'' END  as \"Account\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) =''array'' then cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''observations''->''customer''->>''vcexternalcustid'' else  cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''observations''->''customer''->>''vcexternalcustid'' END  as \"Customer\", hiproinst.end_time_  as  \"Closed Date\", CASE WHEN  hiproinst.state_ = ''ACTIVE'' THEN task.name_ ELSE ''Closed'' END as \"Stage\", task.assignee_ as \"Claimed By\", hiproinst.start_time_  as  \"Created Date\", CASE WHEN hiproinst.state_ != ''ACTIVE'' then ''Closed'' WHEN  task.assignee_ is not null THEN ''Claimed'' ELSE ''Unclaimed'' END as \"Status\", pdef.name_ as \"Case Type\", CASE WHEN  task.assignee_ is not null THEN oplog.time_ ELSE null END  as \"Claimed On\", payer.text_ as \"Payer\", payee.text_ as \"Payee\", TransactionAmount.double_ / 100 as \"Amount\", TicketID.long_ as \"Case ID\", Alert.text_ as \"Alert\" from camunda.act_hi_procinst hiproinst full outer join camunda.act_re_procdef pdef on pdef.id_ = hiproinst.proc_def_id_ full outer join camunda.act_ru_task task on