INSERT INTO ui.emailtemplate(
	id, body, subject, associateid, response, camunda_message_name, itenantid)
SELECT 5, '<p>Hello,</p><p>You have requested to reset your password.</p>
          <p>Click the link below to change your password:</p>
          <p><a th:href="@{${dronauiurl} + ''/auth/reset-password?token='' + ${resetToken}}">Change my password</a></p>
          <br>
          <p>Ignore this email if you do remember your password or you have not made the request</p>', 'Password reset request for DronaPay app', 'drona', NULL, NULL, t.itenantid
FROM ui.tenants t WHERE itenantid =24 AND iorgid = 4
UNION ALL
