 INSERT INTO camunda.act_id_tenant (id_, rev_, name_) 
 SELECT cast(itenantid as VARCHAR), 1, vctenantid from ui.tenants WHERE iorgid = 4 and itenantid =24 ;


 INSERT INTO camunda.act_id_tenant_member(
	id_, tenant_id_, user_id_)
SELECT ENCODE(gen_random_bytes(32), 'hex'), wbm.itenantid::varchar, wbm.webuserid::varchar
	FROM ui.webusermapping wbm 
	join camunda.act_id_user aiu on aiu.id_ = wbm.webuserid::varchar
	where mappingtype='Tenant' and wbm.webuserid in (1, 2) and  wbm.itenantid =24 ;


INSERT INTO ui.webusermapping(
	 mappingid,mappingtype, webuserid, iorgid, itenantid)
SELECT DISTINCT wb.igroupid,'Group',wb1.iuserid,4,24
FROM  ui.groupdesc wb, ui.webuser wb1
WHERE wb.itenantid =24 AND wb1.iorgid = 4 and wb1.iuserid in (1, 2);




