-- Procedure call to create partitions for tenants and organizations
-- DO this after doing insertion into tenant and org table
DO $$ 
DECLARE
iorgid_value INT := 4;

BEGIN
IF iorgid_value <> 0 THEN
CALL masters.partition_for_tenants(iorgid_value);

CALL masters.partition_for_orgs(iorgid_value);

CALL masters.partition_for_tenants(0);

CALL masters.partition_for_orgs(0);


CALL masters.partition_for_tenants_to_trans();

-- time 

CALL masters.add_monthly_partitions_to_trans(
    (CONCAT(TO_CHAR(DATE_TRUNC('month', CURRENT_DATE - INTERVAL '1 month'), 'YYYY'), LPAD(TO_CHAR(DATE_TRUNC('month', CURRENT_DATE - INTERVAL '1 month'), 'MM'), 2, '0'))),
    ((DATE_TRUNC('month', CURRENT_DATE - INTERVAL '1 month'))::date),
    ((DATE_TRUNC('month', CURRENT_DATE) - INTERVAL '1 day')::date)
);

CALL masters.add_monthly_partitions_to_trans(
    (CONCAT(TO_CHAR(CURRENT_DATE, 'YYYY'), LPAD(TO_CHAR(CURRENT_DATE, 'MM'), 2, '0'))),
    (DATE_TRUNC('month', CURRENT_DATE)::date),
    ((DATE_TRUNC('month', CURRENT_DATE) + INTERVAL '1 month')::date)
);


CALL masters.add_monthly_partitions_to_trans(
    (CONCAT(TO_CHAR(DATE_TRUNC('month', CURRENT_DATE + INTERVAL '1 month'), 'YYYY'), LPAD(TO_CHAR(DATE_TRUNC('month', CURRENT_DATE + INTERVAL '1 month'), 'MM'), 2, '0'))),
    ((DATE_TRUNC('month', CURRENT_DATE)+ INTERVAL '1 month')::date),
    ((DATE_TRUNC('month', CURRENT_DATE) + INTERVAL '2 month')::date)
);
ELSE
        -- Output a notice or take appropriate action if iorgid_value is 0
        RAISE NOTICE 'Procedure calls skipped due to iorgid_value being 0.';
    END IF;
END $$;